  "word": "認識する",
  "reading": "にんしきする",
  "romaji": "ninshiki suru",
  "meaning_id": "menyadari, mengakui, mengidentifikasi (secara kognitif)",
  "meaning_en": "to recognize, to be aware of, to identify",
